void sctp_update_association(struct sctp_association *asoc, struct sctp_association *new) {
    if (!asoc || !new) {
        return;
    }

    // Copy new parameters from `new` to `asoc`
    memcpy(&asoc->params, &new->params, sizeof(asoc->params));

    // Remove peer addresses from `asoc` that are not in `new`
    for (int i = 0; i < asoc->num_peer_addrs; ++i) {
        int found = 0;
        for (int j = 0; j < new->num_peer_addrs && !found; ++j) {
            if (memcmp(&asoc->peer_addrs[i], &new->peer_addrs[j], sizeof(struct sockaddr)) == 0) {
                found = 1;
            }
        }
        if (!found) {
            // Remove the address from `asoc`
            memmove(&asoc->peer_addrs[i], &asoc->peer_addrs[i + 1], sizeof(struct sockaddr) * (asoc->num_peer_addrs - i - 1));
            --asoc->num_peer_addrs;
            --i;
        }
    }

    // If the association is established, update next TSN and clear SSN map
    if (asoc->state == SCTP_ESTABLISHED) {
        asoc->next_tsn = new->next_tsn;
        memset(asoc->ssn_map, 0, sizeof(asoc->ssn_map));
        sctp_flush_ulp_reassembly(asoc);
        asoc->error_count = 0;
    } else {
        // Add new peer addresses from `new`
        for (int i = 0; i < new->num_peer_addrs; ++i) {
            int already_exists = 0;
            for (int j = 0; j < asoc->num_peer_addrs && !already_exists; ++j) {
                if (memcmp(&new->peer_addrs[i], &asoc->peer_addrs[j], sizeof(struct sockaddr)) == 0) {
                    already_exists = 1;
                }
            }
            if (!already_exists && asoc->num_peer_addrs < SCTP_MAX_PEER_ADDRS) {
                memcpy(&asoc->peer_addrs[asoc->num_peer_addrs], &new->peer_addrs[i], sizeof(struct sockaddr));
                ++asoc->num_peer_addrs;
            }
        }

        // Manage SSN map and association ID
        if (asoc->ssn_map) {
            free(asoc->ssn_map);
        }
        asoc->ssn_map = malloc(sizeof(uint16_t) * new->ssn_map_size);
        if (asoc->ssn_map) {
            memcpy(asoc->ssn_map, new->ssn_map, sizeof(uint16_t) * new->ssn_map_size);
            asoc->ssn_map_size = new->ssn_map_size;
        }
        asoc->assoc_id = new->assoc_id;
    }

    // Update peer parameters related to SCTP-AUTH
    if (asoc->auth_keys) {
        free(asoc->auth_keys);
    }
    asoc->auth_keys = malloc(sizeof(struct sctp_auth_key) * new->num_auth_keys);
    if (asoc->auth_keys) {
        memcpy(asoc->auth_keys, new->auth_keys, sizeof(struct sctp_auth_key) * new->num_auth_keys);
        asoc->num_auth_keys = new->num_auth_keys;
    }
    asoc->auth_hmac = new->auth_hmac;
    asoc->auth_random = new->auth_random;
    asoc->auth_keyid = new->auth_keyid;
}
